def collinear(p):
    # p strictly between two Ts on some line (orth or diag)
    res=None
    for d in (-1,1):
        for e in (-1,0,1):
            if e==0: continue
            t1=(p[0]+d,p[1]+e); t2=(p[0]-d,p[1]-e)
            if 0<=t1[0]<H and 0<=t1[1]<W and I[t1[0]][t1[1]]==2 and 0<=t2[0]<H and 0<=t2[1]<W and I[t2[0]][t2[1]]==2:
                res=True
    return res
